begin;
with input(id,name,slug,name_normalized,start_date,end_date,location_id,uci_class,description,fingerprint,evidence) as (values ('bc66fdbd-5926-409f-88e9-1e1ae36e7365','Český pohár MTB XCO/XCC — Město Touškov','cesky-pohar-mtb-xco-xcc-mesto-touskov-2027','cesky pohar xcc mesto touskov','2027-04-24','2027-04-25','296f2ee7-b939-4875-a62c-66c8443d6f25','C1','Místo konání: Touškovská rokle. Závod Českého poháru MTB, kategorie UCI C1. Součástí víkendu jsou XCO a XCC. Licence je povinná pro všechny závodníky včetně expertů a masters. Přihlášení pouze online předem, bez dohlášek na místě. Časový plán je předběžný; MČR v Praze a finále v Novém Městě na Moravě budou mít upravený harmonogram. Dětské kategorie nejsou v roce 2027 součástí Českého poháru XCO; případné zařazení dětí 9–10 let pořadatel teprve oznámí.','2027-04-24:nogps:cesky pohar xcc mesto touskov','2027-04-24–2027-04-25 Touškovská rokle C1'),
