(null,'Český pohár MTB XCO/XCC — Bedřichov','cesky-pohar-mtb-xco-xcc-bedrichov-2027','cesky pohar xcc bedrichov','2027-06-05','2027-06-06','8132efee-deec-40c0-848b-f05edfcaa41a','C1','Místo konání: Sportovní stadion. Závod Českého poháru MTB, kategorie UCI C1. Součástí víkendu jsou XCO a XCC. Licence je povinná pro všechny závodníky včetně expertů a masters. Přihlášení pouze online předem, bez dohlášek na místě. Časový plán je předběžný; MČR v Praze a finále v Novém Městě na Moravě budou mít upravený harmonogram. Dětské kategorie nejsou v roce 2027 součástí Českého poháru XCO; případné zařazení dětí 9–10 let pořadatel teprve oznámí.','2027-06-05:nogps:cesky pohar xcc bedrichov','2027-06-05–2027-06-06 Sportovní stadion C1'),
('845dfe98-7911-43f2-8951-697e3644e710','MČR MTB XCC/XCO — Praha — Traily Motol','mcr-mtb-xcc-xco-praha-traily-motol-2027','mcr xcc praha traily motol','2027-07-17','2027-07-18','4d121da2-e5fe-44d0-9f32-7bf69341c957',null,'Místo konání: Motol. Mistrovství České republiky XCO a XCC. Součástí víkendu jsou XCO a XCC. Licence je povinná pro všechny závodníky včetně expertů a masters. Přihlášení pouze online předem, bez dohlášek na místě. Časový plán je předběžný; MČR v Praze a finále v Novém Městě na Moravě budou mít upravený harmonogram. Dětské kategorie nejsou v roce 2027 součástí Českého poháru XCO; případné zařazení dětí 9–10 let pořadatel teprve oznámí.','2027-07-17:nogps:mcr xcc praha traily motol','2027-07-17–2027-07-18 Motol MČR XCO & XCC'),
(null,'Český pohár MTB XCO/XCC — Stupno','cesky-pohar-mtb-xco-xcc-stupno-2027','cesky pohar xcc stupno','2027-08-14','2027-08-15','241d41bf-8a82-4620-a3e1-e01c8ca73d2a','C1','Místo konání: Ultramarínka. Závod Českého poháru MTB, kategorie UCI C1. Součástí víkendu jsou XCO a XCC. Licence je povinná pro všechny závodníky včetně expertů a masters. Přihlášení pouze online předem, bez dohlášek na místě. Časový plán je předběžný; MČR v Praze a finále v Novém Městě na Moravě budou mít upravený harmonogram. Dětské kategorie nejsou v roce 2027 součástí Českého poháru XCO; případné zařazení dětí 9–10 let pořadatel teprve oznámí.','2027-08-14:nogps:cesky pohar xcc stupno','2027-08-14–2027-08-15 Ultramarínka C1'),
(null,'Český pohár MTB XCO/XCC — Nové Město na Moravě','cesky-pohar-mtb-xco-xcc-nove-mesto-na-morave-2027','cesky pohar xcc nove mesto na morave','2027-09-18','2027-09-19','53fe747f-bb64-4770-b73a-21d7691909d6','C1','Místo konání: Vysočina aréna. Závod Českého poháru MTB, kategorie UCI C1. Součástí víkendu jsou XCO a XCC. Licence je povinná pro všechny závodníky včetně expertů a masters. Přihlášení pouze online předem, bez dohlášek na místě. Časový plán je předběžný; MČR v Praze a finále v Novém Městě na Moravě budou mít upravený harmonogram. Dětské kategorie nejsou v roce 2027 součástí Českého poháru XCO; případné zařazení dětí 9–10 let pořadatel teprve oznámí.','2027-09-18:nogps:cesky pohar xcc nove mesto na morave','2027-09-18–2027-09-19 Vysočina aréna C1')),
written as (
insert into events(id,name,slug,name_normalized,start_date,end_date,location_id,uci_class,description,fingerprint,disciplines,series_id,source_kind,website_url,level,event_type,competition_type,season,status,visibility,audience)
select coalesce(id::uuid,gen_random_uuid()),name,slug,name_normalized,start_date::date,end_date::date,location_id::uuid,uci_class,description,fingerprint,array['xco','xcc'],'f5a31302-4fd7-4128-8abc-c1835e7159df'::uuid,'official','https://www.poharmtb.cz/cross-country','national',case when uci_class is null then 'championship' else 'race' end,'national_federation','2027','scheduled','public','mixed' from input
on conflict(id) do update set name=excluded.name,name_normalized=excluded.name_normalized,start_date=excluded.start_date,end_date=excluded.end_date,location_id=excluded.location_id,uci_class=excluded.uci_class,description=excluded.description,fingerprint=excluded.fingerprint,disciplines=excluded.disciplines,series_id=excluded.series_id,source_kind=excluded.source_kind,website_url=excluded.website_url,level=excluded.level,event_type=excluded.event_type,competition_type=excluded.competition_type,last_seen_at=now(),updated_at=now()
returning *
), overrides as (
insert into event_overrides(event_id,fields,locked_fields,updated_by)
select id,jsonb_build_object('name',name,'start_date',start_date,'end_date',end_date,'location_id',location_id,'website_url',website_url,'disciplines',disciplines,'series_id',series_id,'uci_class',uci_class,'level',level,'event_type',event_type,'competition_type',competition_type),
array['name','start_date','end_date','location_id','website_url','disciplines','series_id','uci_class','level','event_type','competition_type'],'manual official poharmtb 2027 2026-10-29' from written
on conflict(event_id) do update set fields=event_overrides.fields || excluded.fields,locked_fields=array(select distinct unnest(event_overrides.locked_fields || excluded.locked_fields)),updated_by=excluded.updated_by,updated_at=now() returning event_id
), memberships as (
insert into event_series(event_id,series_id,is_primary,source)
select id,series_id,true,'manual official poharmtb 2027 2026-10-29' from written
on conflict(event_id,series_id) do update set is_primary=true,source=excluded.source,updated_at=now() returning event_id
), facts as (
insert into event_facts(event_id,field,value,previous,source_url,quote,method,version)
select w.id,'calendar_2027',jsonb_build_object('name',w.name,'start_date',w.start_date,'end_date',w.end_date,'disciplines',w.disciplines,'uci_class',w.uci_class),null,'https://www.poharmtb.cz/cross-country',i.evidence,'manual','poharmtb-2027-2026-10-29'
from written w join input i on i.name=w.name returning event_id)
select id,name,start_date,end_date,slug from written order by start_date;
update event_sources set is_canonical=false where event_id in(select id from events where series_id='f5a31302-4fd7-4128-8abc-c1835e7159df' and season='2027') and source_url <> 'https://www.poharmtb.cz/cross-country';
insert into event_sources(event_id,source_url,kind,is_canonical,external_id)
select e.id,'https://www.poharmtb.cz/cross-country','official',true,'poharmtb-2027-'||e.start_date from events e where e.series_id='f5a31302-4fd7-4128-8abc-c1835e7159df' and e.season='2027' and not exists(select 1 from event_sources s where s.event_id=e.id and s.source_url='https://www.poharmtb.cz/cross-country');
commit;
